import{_ as t,o as l,c as e,a2 as i}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"推奨ローカルモデル","description":"显存に応じたローカル大モデル推奨（通路検証、ロールプレイ、中国語）；Ollama、LM Studio、KoboldCPP、llama.cpp と MiniTavern。","frontmatter":{"title":"推奨ローカルモデル","description":"显存に応じたローカル大モデル推奨（通路検証、ロールプレイ、中国語）；Ollama、LM Studio、KoboldCPP、llama.cpp と MiniTavern。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"推奨ローカルモデル · MiniTavern Docs"}],["meta",{"property":"og:description","content":"显存に応じたローカル大モデル推奨（通路検証、ロールプレイ、中国語）；Ollama、LM Studio、KoboldCPP、llama.cpp と MiniTavern。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/local/models"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/local/models"}]]},"headers":[],"relativePath":"ja/local/models.md","filePath":"ja/local/models.md","lastUpdated":1787224147000}'),o={name:"ja/local/models.md"};function n(r,a,d,s,h,p){return l(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="推奨モデル" tabindex="-1">推奨モデル <a class="header-anchor" href="#推奨モデル" aria-label="Permalink to &quot;推奨モデル&quot;">​</a></h1><p>モデル名と取得方法はツールごとに異なる；下表は <strong>体量と用途</strong> の目安。具体的な pull／ファイル名は各ツールページ準拠。</p><h2 id="ハードウェアで体量を選ぶ" tabindex="-1">ハードウェアで体量を選ぶ <a class="header-anchor" href="#ハードウェアで体量を選ぶ" aria-label="Permalink to &quot;ハードウェアで体量を選ぶ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>おおよその規模</th><th>メモリ／显存の目安</th><th>向く用途</th></tr></thead><tbody><tr><td>1B–3B</td><td>約 4–8GB</td><td><strong>まず通路を検証</strong>、低スペック</td></tr><tr><td>7B–9B</td><td>約 8–16GB</td><td>ロールプレイのよくあるスイートスポット</td></tr><tr><td>12B–14B</td><td>16GB+</td><td>品質向上、速度は GPU 次第</td></tr><tr><td>32B+</td><td>24GB+ または強い量子化</td><td>高スペック；スマホ接続でも待ちが長い</td></tr></tbody></table><p>量子化（Q4／Q5／IQ など）が小さいほど省リソース、品質は少し下がる。GGUF はコミュニティ定番の <code>Q4_K_M</code>／<code>Q5_K_M</code> を優先。</p><h2 id="通路検証-小モデル優先" tabindex="-1">通路検証（小モデル優先） <a class="header-anchor" href="#通路検証-小モデル優先" aria-label="Permalink to &quot;通路検証（小モデル優先）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>シーン</th><th>Ollama 例</th><th>GGUF／その他</th></tr></thead><tbody><tr><td>最速で測通</td><td><code>llama3.2:3b</code>、<code>qwen2.5:3b</code></td><td>任意の 3B 級 instruct GGUF</td></tr><tr><td>中国語軽量</td><td><code>qwen2.5:3b</code>／<code>qwen2.5:7b</code></td><td>Qwen2.5 Instruct 量子化</td></tr></tbody></table><p>先に <a href="/ultra_guides/ja/connect-app/minitavern">測連成功</a> してから大モデルへ。</p><h2 id="ロールプレイ向けのヒント" tabindex="-1">ロールプレイ向けのヒント <a class="header-anchor" href="#ロールプレイ向けのヒント" aria-label="Permalink to &quot;ロールプレイ向けのヒント&quot;">​</a></h2><ul><li><strong>Instruct／Chat</strong> 微調を優先し、純基座の補完モデルは避ける。</li><li>コミュニティで語られる RP 向け重みは時期で変わる；ツールで安定ロードでき、コンテキスト長が足りるものを正とする。</li><li>コンテキストが小さすぎると長設定／ワールドブックが切れる；7B 級はまず 4k–8k から試し、显存に応じて拡大。</li><li>MiniTavern に記入する <strong>モデル名</strong> はツール一覧と <strong>完全一致</strong>（tag 含む、例 <code>:7b</code>）。</li></ul><h2 id="ollama-よくある-pull-例" tabindex="-1">Ollama よくある pull 例 <a class="header-anchor" href="#ollama-よくある-pull-例" aria-label="Permalink to &quot;Ollama よくある pull 例&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:7b</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:14b</span></span></code></pre></div><p>コマンド詳細は <a href="/ultra_guides/ja/ollama/models">Ollama · モデルの取得と選択</a>。</p><h2 id="lm-studio-koboldcpp-llama-cpp" tabindex="-1">LM Studio／KoboldCPP／llama.cpp <a class="header-anchor" href="#lm-studio-koboldcpp-llama-cpp" aria-label="Permalink to &quot;LM Studio／KoboldCPP／llama.cpp&quot;">​</a></h2><ol><li><a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a> などから <strong>GGUF</strong> を取得（ライセンスと出所の信頼性に注意）。</li><li>対応ツールで同一ファイルをロード。</li><li>API／Server を開き、UI 表示の <strong>model id</strong> を MiniTavern へ転記。</li></ol><h2 id="次のステップ" tabindex="-1">次のステップ <a class="header-anchor" href="#次のステップ" aria-label="Permalink to &quot;次のステップ&quot;">​</a></h2><p><a href="./tools">ツール一覧</a> → 選んだツールの「サービス開始」章 → <a href="/ultra_guides/ja/connect-app/minitavern">MiniTavern での設定</a></p>`,17)])])}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
